const banCommand = new SlashCommandBuilder().setName('ban').setDescription('Ban a user from the server.').addUserOption((option) => option.setName('user').setDescription('The user to ban, specified by their ID or mention')).addStringOption((option) => option.setName('reason').setDescription('The reason for banning the user')).toJSON();
