// Converts a string to lowercase
void to_lower(std::string& str) {
  std::transform(str.begin(), str.end(), str.begin(), ::tolower);
}

// Checks if two strings are equal, ignoring case
bool case_insensitive_equal(const std::string& str1, const std::string& str2) {
  size_t len = str1.length();
  if (len != str2.length()) return false;
  for (size_t i = 0; i < len; ++i)
    if (std::tolower(static_cast<unsigned char>(str1[i]))
        != std::tolower(static_cast<unsigned char>(str2[i])))
      return false;
  return true;
}

// Splits a string into words
std::istringstream& split(std::istringstream& is, std::vector<std::string>& v, char delim) {
  std::string x;
  while (is >> x)
    v.push_back(x), is.ignore(1);
  return is;
}

// Counts the occurrences of a target_word in a given line
int count_occurrences(const std::string& line, const std::string& target_word) {
  int count = 0;
  std::string temp;

  // Split line into words
  std::istringstream line_stream(line);
  std::vector<std::string> words;
  split(line_stream, words, ' ');

  // Compare each word with the target_word, incrementing the counter on a match
  for (auto& w : words)
  {
    to_lower(w);
    to_lower(target_word);

    if (case_insensitive_equal(w, target_word))
      ++count;
  }

  return count;
}
